  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --input: rgba(15, 23, 42, 0.8);
      --input-border: rgba(148, 163, 184, 0.24);
      --error: #fda4af;
      --success: #86efac;
      --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(14, 165, 233, 0.18), transparent 34%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 560px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.9rem, 4vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
      letter-spacing: 0.01em;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid var(--input-border);
      border-radius: 12px;
      background: var(--input);
      color: var(--text);
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
      transform: translateY(-1px);
    }

    .helper-text,
    .field-error,
    .form-status {
      font-size: 0.95rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .field-error {
      margin: 0;
      color: var(--error);
      min-height: 1.4em;
    }

    .form-field.invalid input {
      border-color: #fb7185;
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 20px;
      font: inherit;
      font-weight: 700;
      color: #020617;
      background: linear-gradient(135deg, var(--accent) 0%, #7dd3fc 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 14px 32px rgba(14, 165, 233, 0.24);
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(125, 211, 252, 0.7);
      outline-offset: 3px;
    }

    .form-status {
      margin: 4px 0 0;
      min-height: 1.4em;
      color: var(--success);
    }

    @media (max-width: 640px) {
      .support-card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Send your details and our team will reach out to help with your request.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="full-name-error"
        >
        <p id="full-name-error" class="field-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input
          id="email-address"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="email-address-error"
        >
        <p id="email-address-error" class="field-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phone"
          type="tel"
          autocomplete="tel"
          inputmode="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-helper phone-number-error"
        >
        <p id="phone-helper" class="helper-text">Expected format: (555) 123-4567 or +1 555 123 4567.</p>
        <p id="phone-number-error" class="field-error" aria-live="polite"></p>
      </div>

      <button type="submit">Submit request</button>
      <p id="form-status" class="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fieldConfig = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          return "";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }
          const phonePattern = /^[+]?[0-9()\s-]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Use digits, spaces, parentheses, or hyphens only.";
          }
          return "";
        }
      }
    ];

    function setFieldState(input, errorElement, message) {
      const formField = input.closest(".form-field");
      errorElement.textContent = message;
      input.setAttribute("aria-invalid", message ? "true" : "false");
      formField.classList.toggle("invalid", Boolean(message));
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field.input, field.error, message);
      return !message;
    }

    fieldConfig.forEach((field) => {
      field.input.addEventListener("blur", () => {
        validateField(field);
      });

      field.input.addEventListener("input", () => {
        if (field.error.textContent) {
          validateField(field);
        }
        if (statusMessage.textContent) {
          statusMessage.textContent = "";
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = fieldConfig.every(validateField);

      if (!isValid) {
        statusMessage.textContent = "";
        const firstInvalidField = fieldConfig.find((field) => field.error.textContent);
        if (firstInvalidField) {
          firstInvalidField.input.focus();
        }
        return;
      }

      statusMessage.textContent = "Your message is ready to send.";
      form.reset();
      fieldConfig.forEach((field) => setFieldState(field.input, field.error, ""));
    });
  </script>
</body>
</html>
