<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Send your details and our team will reach out to help with your request.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="full-name-error"
        >
        <p id="full-name-error" class="field-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input
          id="email-address"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="email-address-error"
        >
        <p id="email-address-error" class="field-error" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phone"
          type="tel"
          autocomplete="tel"
          inputmode="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-helper phone-number-error"
        >
        <p id="phone-helper" class="helper-text">Expected format: (555) 123-4567 or +1 555 123 4567.</p>
        <p id="phone-number-error" class="field-error" aria-live="polite"></p>
      </div>

      <button type="submit">Submit request</button>
      <p id="form-status" class="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");

    const fieldConfig = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          return "";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }
          const phonePattern = /^[+]?[0-9()\s-]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Use digits, spaces, parentheses, or hyphens only.";
          }
          return "";
        }
      }
    ];

    function setFieldState(input, errorElement, message) {
      const formField = input.closest(".form-field");
      errorElement.textContent = message;
      input.setAttribute("aria-invalid", message ? "true" : "false");
      formField.classList.toggle("invalid", Boolean(message));
    }

    function validateField(field) {
      const message = field.validate(field.input.value);
      setFieldState(field.input, field.error, message);
      return !message;
    }

    fieldConfig.forEach((field) => {
      field.input.addEventListener("blur", () => {
        validateField(field);
      });

      field.input.addEventListener("input", () => {
        if (field.error.textContent) {
          validateField(field);
        }
        if (statusMessage.textContent) {
          statusMessage.textContent = "";
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = fieldConfig.every(validateField);

      if (!isValid) {
        statusMessage.textContent = "";
        const firstInvalidField = fieldConfig.find((field) => field.error.textContent);
        if (firstInvalidField) {
          firstInvalidField.input.focus();
        }
        return;
      }

      statusMessage.textContent = "Your message is ready to send.";
      form.reset();
      fieldConfig.forEach((field) => setFieldState(field.input, field.error, ""));
    });
  </script>
